import { addLog, checkBuild, clearLogs, ErrorLog, SpinnerLog } from '@mintlify/previewing';
import path from 'node:path';
import { format } from 'node:util';

import { CMD_EXEC_PATH, errorMessage, getVersions, terminate } from '../helpers.js';
import { resolveExplicitFiles } from '../resolveFiles.js';
import { sendPublishPrompt } from '../signup.js';
import { checkSite, runBuildChecks, selectRules } from './engine.js';
import { logReport } from './output.js';
import { toReport, type BuildStatus } from './report.js';

export type ValidateArgs = {
  'local-schema': boolean;
  'client-version'?: string;
  groups?: (string | number)[];
  files?: (string | number)[];
  build: boolean;
  enable?: string[];
  disable?: string[];
  fix: boolean;
  format: 'text' | 'json';
};

export const EXIT = { passed: 0, failed: 1, crashed: 2 } as const;

export const splitList = (values: string[]) =>
  values.flatMap((value) =>
    value
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)
  );

const write = (text: string) =>
  new Promise<void>((resolve) => {
    process.stdout.write(text, () => resolve());
  });

/**
 * Writes console output straight to stderr, so --format json leaves stdout to the report. Ink
 * patches console and redraws on stdout, so redirecting to console.error isn't enough.
 */
const consoleToStderr = () => {
  const original = {
    log: console.log,
    info: console.info,
    warn: console.warn,
    error: console.error,
  };
  const toStderr = (...args: unknown[]) => {
    process.stderr.write(`${format(...args)}\n`);
  };
  console.log = console.info = console.warn = console.error = toStderr;
  return () => Object.assign(console, original);
};

const resolveSelection = async (baseDir: string, values: (string | number)[] | undefined) => {
  const args = (values ?? []).map(String).filter(Boolean);
  if (args.length === 0) return undefined;
  const files = await resolveExplicitFiles(CMD_EXEC_PATH, args);
  return new Set(
    files.map((file) =>
      path.relative(baseDir, path.resolve(CMD_EXEC_PATH, file)).split(path.sep).join('/')
    )
  );
};

/** mint validate: one pass over every selected rule, then the strict build when nothing failed. */
export const validateHandler = async (
  argv: ValidateArgs,
  packageName: string,
  baseDir = CMD_EXEC_PATH
) => {
  const json = argv.format === 'json';
  const restoreConsole = json ? consoleToStderr() : undefined;
  try {
    const rules = selectRules({
      enable: argv.enable,
      disable: argv.disable ?? [],
    });
    const selected = await resolveSelection(baseDir, argv.files);
    if (!json) addLog(<SpinnerLog message="validating..." />);

    const { site, fixed, ...checked } = await checkSite(baseDir, rules, {
      selected,
      localSchema: argv['local-schema'],
      fix: argv.fix,
    });
    let { diagnostics } = checked;

    const buildRules = rules.some(({ needsBuild }) => needsBuild);
    let build: BuildStatus;
    if (!argv.build) {
      build = { ran: false, reason: 'disabled' };
    } else if (!buildRules) {
      build = { ran: false, reason: 'no build rules' };
    } else if (diagnostics.some(({ severity }) => severity === 'error')) {
      build = { ran: false, reason: 'errors found' };
    } else {
      if (!json) addLog(<SpinnerLog message="building..." />);
      const { cli: cliVersion } = getVersions(packageName);
      site.build = await checkBuild({
        ...argv,
        _: [],
        $0: packageName,
        packageName,
        cliVersion,
        disableOpenapi: !rules.some(({ group }) => group === 'openapi'),
      });
      diagnostics = await runBuildChecks(site, rules, diagnostics);
      build = { ran: true, passed: site.build.passed };
    }

    const report = toReport(diagnostics, build, argv.fix ? fixed : undefined);
    if (json) {
      restoreConsole?.();
      await write(`${JSON.stringify(report)}\n`);
    } else {
      clearLogs();
      logReport(report);
      if (report.passed && build.ran && build.passed) await sendPublishPrompt();
    }
    await terminate(report.passed ? EXIT.passed : EXIT.failed);
  } catch (error) {
    // Bad arguments and crashes alike mean validate could not run
    if (json) {
      restoreConsole?.();
      process.stderr.write(`Error: ${errorMessage(error)}\n`);
    } else {
      clearLogs();
      addLog(<ErrorLog message={errorMessage(error)} />);
    }
    await terminate(EXIT.crashed);
  }
};
